import{_ as t,o as a,c as i,a3 as n}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"The ThinLTO Cache","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"The ThinLTO Cache | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/features/thinlto-cache"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/features/thinlto-cache"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/features/thinlto-cache"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/features/thinlto-cache"}]]},"headers":[],"relativePath":"xclang/features/thinlto-cache.md","filePath":"en/xclang/features/thinlto-cache.md","lastUpdated":1791238464000}'),s={name:"xclang/features/thinlto-cache.md"};function o(h,e,l,r,c,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-thinlto-cache" tabindex="-1">The ThinLTO Cache <a class="header-anchor" href="#the-thinlto-cache" aria-label="Permalink to &quot;The ThinLTO Cache&quot;">​</a></h1><p><a href="./libclang">libclang</a> ships as ThinLTO bitcode, so the link of a tool on it compiles the clang libraries to machine code: minutes per link. The ThinLTO cache of the linker keeps that code between links, and a relink after a small change takes seconds. This page is also the home of the cache measurements.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><p><code>XCLANG_THINLTO_CACHE</code> names an absolute directory for the cache, the same way in every build system. Use one fixed path per OS: <code>/var/tmp/xclang-thinlto</code> on Linux and macOS, <code>C:/xclang-thinlto</code> on Windows (<a href="#why-one-fixed-path">why</a>).</p><h3 id="cmake" tabindex="-1">CMake <a class="header-anchor" href="#cmake" aria-label="Permalink to &quot;CMake&quot;">​</a></h3><p>Set it before <code>find_package(xclang)</code>, or in the environment. The tool of <a href="./libclang#cmake">libclang</a> sets it when it configures:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -G</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_CXX_COMPILER=clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DCMAKE_BUILD_TYPE=Release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -DCMAKE_PREFIX_PATH=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/libclang&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DXCLANG_THINLTO_CACHE=/var/tmp/xclang-thinlto</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The first link fills the cache. After a change, the link takes the code of the libraries from it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.cpp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="bazel" tabindex="-1">Bazel <a class="header-anchor" href="#bazel" aria-label="Permalink to &quot;Bazel&quot;">​</a></h3><p>Name it in the <code>.bazelrc</code> of the project, with one path per OS, as <a href="https://github.com/clice-io/xclang/tree/main/examples/libclang" target="_blank" rel="noreferrer">examples/libclang</a> does:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>common:linux --repo_env=XCLANG_THINLTO_CACHE=/var/tmp/xclang-thinlto</span></span>
<span class="line"><span>common:linux --sandbox_writable_path=/var/tmp/xclang-thinlto</span></span>
<span class="line"><span>common:macos --repo_env=XCLANG_THINLTO_CACHE=/var/tmp/xclang-thinlto</span></span>
<span class="line"><span>common:windows --repo_env=XCLANG_THINLTO_CACHE=C:/xclang-thinlto</span></span>
<span class="line"><span>try-import %workspace%/user.bazelrc</span></span></code></pre></div><p>A user who needs another path says so in <code>user.bazelrc</code>. Those links then have keys of their own, which a shared cache does not serve:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>common:linux --repo_env=XCLANG_THINLTO_CACHE=/data/xclang-thinlto</span></span>
<span class="line"><span>common:linux --sandbox_writable_path=/data/xclang-thinlto</span></span></code></pre></div><h3 id="plain-clang" tabindex="-1">Plain Clang <a class="header-anchor" href="#plain-clang" aria-label="Permalink to &quot;Plain Clang&quot;">​</a></h3><p>Pass the cache flag of the linker: <code>-Wl,--thinlto-cache-dir=&lt;dir&gt;</code> for Linux and MinGW targets, <code>-Wl,-cache_path_lto,&lt;dir&gt;</code> for macOS targets, and <code>-Wl,/lldltocache:&lt;dir&gt;</code> for the <a href="./../design/roadmap#msvc">unreleased</a> MSVC targets. The CMake package and the Bazel module pass the same flags.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>CMake</th><th>Bazel</th></tr></thead><tbody><tr><td>turn it on</td><td><code>-DXCLANG_THINLTO_CACHE=&lt;dir&gt;</code>, or the environment variable, before <code>find_package(xclang)</code></td><td><code>--repo_env=XCLANG_THINLTO_CACHE=&lt;dir&gt;</code></td></tr><tr><td>where it applies</td><td>every link of the directory that called <code>find_package(xclang)</code>, and of its subdirectories</td><td>every link, through the <code>thinlto_cache</code> feature</td></tr><tr><td>turn it off</td><td>leave the variable unset</td><td><code>--features=-thinlto_cache</code> for a build, <code>features = [&quot;-thinlto_cache&quot;]</code> for a Bazel target</td></tr><tr><td>the directory</td><td>made at configure time</td><td>made by the Bazel module, again whenever it is gone</td></tr></tbody></table><p>Without the variable, no link has a cache flag.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>What it keeps.</strong> lld&#39;s ThinLTO cache keeps the machine code of each bitcode file in the directory, under a hash of everything that went into it: the bitcode, the summaries of what it imports, and the options. A later link generates only the code whose hash changed, and takes the rest from the directory.</li><li><strong>The program is the same</strong> with and without the cache. An entry is found only by the hash of exactly what produced it, so it can make a link faster, but not different.</li><li><strong>Builds can share a directory.</strong> An entry is written whole or not at all.</li><li><strong>Pruning.</strong> At most every 20 minutes, the linker removes the entries no link has read for a week, which is LLVM&#39;s default policy. A CI cache defeats that; keeping the directory in CI is in <a href="./../integrations/ci#keep-caches-between-runs">CI</a>.</li></ul><h3 id="why-bitcode" tabindex="-1">Why Bitcode <a class="header-anchor" href="#why-bitcode" aria-label="Permalink to &quot;Why Bitcode&quot;">​</a></h3><p>A tool built on clang (a language server, a linter, a refactoring tool) spends its time in the code of clang: the parser, Sema, the AST. Shipped as machine code, those libraries are optimized on their own, and the tool calls into them across a boundary no optimizer crosses.</p><p>Shipped as ThinLTO bitcode, built with the same PGO profile as xclang&#39;s clang, they are optimized together with the tool at its link: inlining across the boundary, dead code dropped, the layout of the profile kept.</p><p>The cost is the link. ThinLTO compiles every bitcode file the tool uses to machine code during the link, in parallel. For a tool on clang, that is most of LLVM and clang, and every relink does it again, even after a one-line change. The cache removes that cost.</p><h3 id="why-one-fixed-path" tabindex="-1">Why One Fixed Path <a class="header-anchor" href="#why-one-fixed-path" aria-label="Permalink to &quot;Why One Fixed Path&quot;">​</a></h3><p><strong>The path is in the key of the link.</strong> The directory is on the command line of the link, so in Bazel it is part of the action key. A disk or remote cache serves a link only to a build that names the same directory. A directory under the workspace or the home directory differs between checkouts and machines, and no link is ever shared. So a project names one path per OS, the same everywhere.</p><p><strong>The sandbox must let the link write it.</strong> The Linux sandbox of Bazel mounts the file system read-only, except for the outputs of the action. <code>--sandbox_writable_path=&lt;dir&gt;</code> makes the cache directory writable, and is not part of any key. A path is made writable only if it exists when the action starts, so the Bazel module creates the directory when the repository is set up, and again whenever it is gone.</p><p><strong>Not under <code>/tmp</code>.</strong> The Linux sandbox gives every action a <code>/tmp</code> of its own. A cache there is written into the private <code>/tmp</code> of the action, and lost without a word. The macOS sandbox lets <code>/var/tmp</code> be written. Bazel runs Windows actions without a sandbox by default.</p><p><strong>Safe outside Bazel&#39;s view.</strong> Bazel treats an action as a function of its declared inputs, and a directory the link reads and writes is state Bazel cannot see. It is safe here because the cache is content-addressed.</p><h2 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h2><p>Measured with 23.1.2.4 on clice&#39;s links of libclang&#39;s bitcode, on GitHub-hosted runners: Linux x64 with 4 cores, macOS arm64 with 3 cores, Windows x64 with 4 cores. The times are those of the link alone, from the profile of Bazel (<a href="https://github.com/clice-io/clice/actions/runs/37041436235" target="_blank" rel="noreferrer">clice runs</a><a href="https://github.com/clice-io/clice/actions/runs/37047279320" target="_blank" rel="noreferrer">37047279320</a><a href="https://github.com/clice-io/clice/actions/runs/37065094747" target="_blank" rel="noreferrer">37065094747</a><a href="https://github.com/clice-io/clice/actions/runs/37075525831" target="_blank" rel="noreferrer">37075525831</a>, branch <code>exp/bazel-lto</code>):</p><table tabindex="0"><thead><tr><th></th><th>Linux x64</th><th>macOS arm64</th><th>Windows x64</th></tr></thead><tbody><tr><td>no cache</td><td>353 s</td><td>190 s</td><td>400–506 s</td></tr><tr><td>empty cache</td><td>357 s</td><td>190–200 s</td><td>492 s</td></tr><tr><td>full cache, nothing changed</td><td>6.1–6.3 s</td><td>4.8–5.1 s</td><td>7.6–14 s</td></tr><tr><td>full cache, one source changed</td><td>6.2 s</td><td>4.7–7.3 s</td><td>14 s</td></tr><tr><td>first link on a fresh runner after restoring the cache, with a change</td><td>6.2 s</td><td>15.6 s</td><td>13.7 s</td></tr><tr><td>cache size</td><td>352–403 MiB</td><td>414–425 MiB</td><td>394–660 MiB</td></tr></tbody></table><p>In 23.1.2.4, macOS targets linked with Apple&#39;s ld and xclang&#39;s libLTO (<code>-cache_path_lto</code>); from 23.1.2.5 on, they link with ld64.lld.</p><p>The tests of 23.1.2.6 link a small tool on libclang without the cache, with an empty one, and with a full one, on every host: 7 to 20 s cold, 0.6 to 1.7 s warm, 152 to 155 entries, and the same program bytes each time (<a href="./../dev/testing#bazel-module">testing</a>).</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./libclang">libclang</a>: the bitcode the cache is for.</li><li><a href="./../integrations/ci#keep-caches-between-runs">CI</a>: keeping the cache between runs.</li></ul>`,37)])])}const u=t(s,[["render",o]]);export{g as __pageData,u as default};
